exercises.solution:
import statistics


def forme(valeurs):
    moyenne = statistics.mean(valeurs)
    mediane = statistics.median(valeurs)
    if moyenne > mediane * 1.1:
        return "étirée à droite"
    if moyenne < mediane * 0.9:
        return "étirée à gauche"
    return "symétrique"
